<?php require 'config.php';auth();$s=$db->prepare('SELECT e.* FROM events e JOIN registrations r ON r.event_id=e.id WHERE r.user_id=? ORDER BY e.event_date');$s->execute([$_SESSION['uid']]);head('My registrations');?><h1>My registrations</h1><div class="grid"><?php foreach($s as $e):?><article class="card"><h3><?=h($e['title'])?></h3><p><?=h($e['venue'])?> — <?=h($e['event_date'])?></p><form method="post" action="registration.php"><input type="hidden" name="token" value="<?=h(token())?>"><input type="hidden" name="event_id" value="<?=h($e['id'])?>"><input type="hidden" name="action" value="cancel"><button>Cancel registration</button></form></article><?php endforeach;?></div><?php foot();?>